require __DIR__ . '/_l.php';
require __DIR__ . '/../includes/report.php';
[$from, $to, $range] = report_range($_GET, '7hari');
$r = report_data($d, $from, $to);
$today = date('Y-m-d');
$pdfUrl = 'laporan-pdf.php?from=' . $from . '&to=' . $to;
$GLOBALS['noh1'] = true;
a_head('Laporan');
